package ama.api;
import ama.meeting.*;import ama.storage.*;import ama.transcript.*;import ama.minutes.ControlledMinutesDataSource;import ama.contract.IdentityContracts.*;import ama.contract.MeetingContracts.*;import java.util.*;import java.nio.file.*;import java.sql.*;import java.lang.reflect.*;import javax.sql.DataSource;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.AbstractDataSource;import org.springframework.core.env.*;import com.fasterxml.jackson.databind.ObjectMapper;
/** A real saved external-name roster, configured acquisition limit, and ordinary SAVE/CONFIRM paths. */
public final class LocalRosterBudgetCheck {
 static void check(boolean b,String m){if(!b)throw new IllegalStateException(m);}
 static final class Source extends AbstractDataSource {
  final DataSource delegate;boolean armed;int raw,metadata;Source(DataSource d){delegate=d;}
  static Object invoke(Object o,Method m,Object[] a)throws Throwable{try{return m.invoke(o,a);}catch(InvocationTargetException e){throw e.getCause();}}
  Object proxy(Object o,Class<?> t,InvocationHandler h){return Proxy.newProxyInstance(t.getClassLoader(),new Class[]{t},h);}
  static boolean rawName(String sql){int end=sql.indexOf(" FROM roster_member");if(end<0)return false;String projection=sql.substring(0,end);return java.util.regex.Pattern.compile("(?i)(?:SELECT\\s+|,)\\s*(?:[a-z_]+\\.)?(?:display_name|\\*)\\s*(?:,|$)").matcher(projection).find();}
  Connection wrap(Connection actual){return(Connection)proxy(actual,Connection.class,(p,m,a)->{if(m.getName().equals("equals"))return p==a[0];if(m.getName().equals("hashCode"))return System.identityHashCode(p);Object result=invoke(actual,m,a);if(m.getName().equals("prepareStatement")&&a[0] instanceof String sql&&result instanceof PreparedStatement st)return proxy(st,PreparedStatement.class,(s,sm,sa)->{
    if(armed&&sm.getName().equals("executeQuery")&&sql.contains("FROM roster_member")){if(rawName(sql))raw++;else if(sql.contains("OCTET_LENGTH(display_name)"))metadata++;}
    Object value=invoke(st,sm,sa);if(armed&&sm.getName().equals("executeUpdate")&&sql.startsWith("UPDATE meeting SET revision="))throw new SQLException("LOCAL_ROSTER_AFTER_UNBOUNDED_READ_WRITE_GUARD");return value;
   });return result;});}
  public Connection getConnection()throws SQLException{return wrap(delegate.getConnection());}public Connection getConnection(String u,String p)throws SQLException{return wrap(delegate.getConnection(u,p));}
 }
 public static void main(String[] args)throws Exception{
  check("1".equals(System.getenv("AMA_LOCAL_DEV"))&&args.length==2,"Explicit current roster budget qualification required");Path file=Path.of(args[0]).toRealPath(),out=Path.of(args[1]).toRealPath();check(file.getParent().endsWith(Path.of(".tools/local-app"))&&out.startsWith(file.getParent().resolve("roster-budget")),"Fresh owned evidence required");var p=new Properties();try(var in=Files.newInputStream(file)){p.load(in);}String url=p.getProperty("database.url");check(url.matches("jdbc:mysql://127\\.0\\.0\\.1:[0-9]+/ama_local_dev\\?.+"),"Owned DB required");var source=new Source(ControlledMinutesDataSource.create(url,p.getProperty("database.user"),p.getProperty("database.password")));var j=new JdbcTemplate(source);j.setQueryTimeout(5);var env=new StandardEnvironment();env.getPropertySources().addFirst(new PropertiesPropertySource("daily",p));var configured=ConfiguredProcessing.read(env);var actor=new Actor("dev-owner",Status.ACTIVE,Set.of(Role.USER));var factory=new MeetingConfiguration();
  try(var definitions=ConfiguredBackends.read(env);var client=ConfiguredPublication.read(env,configured.read(),configured.index()).client()){
   var catalog=new FileBackendCatalog(source,definitions.backends(),definitions.defaultId());catalog.configure();var runtime=LocalAcquisitionBudgetCheck.build(source,env,catalog,client);var normal=factory.meetingRepository(source,runtime.tx(),runtime.access(),runtime.fences(),runtime.outbox(),factory.companyMeetingCategories(),runtime.processing(),factory.workspaceReadLimits(env));var created=normal.create(actor,UUID.randomUUID().toString(),UUID.randomUUID().toString());String meeting=created.id();String name="名😀".repeat(12000);var saved=normal.save(actor,meeting,UUID.randomUUID().toString(),new SaveInfo(0L,"正常业务建立名单预算夹具",null,null,null,List.of(),List.of(name)),UUID.randomUUID().toString());var before=LocalMeetingInfoRollbackCheck.snapshot(j,meeting);
   env.getPropertySources().addFirst(new MapPropertySource("actual-acquisition-cap",Map.of("workspace.read.max-acquisition-bytes","262144")));var bounded=factory.meetingRepository(source,runtime.tx(),runtime.access(),runtime.fences(),runtime.outbox(),factory.companyMeetingCategories(),runtime.processing(),factory.workspaceReadLimits(env));var cases=new ArrayList<Map<String,Object>>();
   for(String mode:List.of("SAVE","CONFIRM")){
    source.raw=0;source.metadata=0;source.armed=true;boolean unavailable=false;RuntimeException thrown=null;try{if(mode.equals("SAVE"))bounded.save(actor,meeting,UUID.randomUUID().toString(),new SaveInfo(saved.revision(),"预算边界不能提交",null,null,null,List.of(),List.of(name)),UUID.randomUUID().toString());else bounded.confirm(actor,meeting,UUID.randomUUID().toString(),new ConfirmRoster(saved.revision()),UUID.randomUUID().toString());}catch(WorkspaceReadBudget.Unavailable failure){unavailable=true;thrown=failure;}catch(RuntimeException failure){thrown=failure;}finally{source.armed=false;}
    check(before.equals(LocalMeetingInfoRollbackCheck.snapshot(j,meeting)),"Qualification failure must not commit any graph/root/receipt/audit/outbox");cases.add(Map.of("operation",mode,"configuredBudgetRejected",unavailable,"rawRosterNameQueriesBeforeReject",source.raw,"nameMetadataQueries",source.metadata,"failureClass",thrown==null?"NONE":thrown.getClass().getName()));
   }
   boolean pass=cases.stream().allMatch(x->Boolean.TRUE.equals(x.get("configuredBudgetRejected"))&&((Number)x.get("rawRosterNameQueriesBeforeReject")).intValue()==0);var report=Map.of("pass",pass,"meetingId",meeting,"externalNameUtf8Bytes",name.getBytes(java.nio.charset.StandardCharsets.UTF_8).length,"configuredAcquisitionByteLimit",262144,"realBusinessOrigin",true,"genuineFactoriesAndSharedInstances",true,"cases",cases,"noSqlBusinessFixtures",true,"snapshotUnchangedAfterProbes",true);Files.writeString(out.resolve("report.json"),new ObjectMapper().writeValueAsString(report));System.out.println(new ObjectMapper().writeValueAsString(report));check(pass,"Saved roster LONGTEXT must be admitted before raw acquisition in both commands");
  }
 }
}
